# -*- coding: utf-8 -*-
# Shared static blocks (copied from build v1)
STRUCT = '''
<section id="aufbau"><h2>Aufbau eines Briefs <small>Structure of a letter</small></h2>
<div class="grid">
<div class="card"><h3>1 · Kopf und Anrede</h3><p class="en">Header and salutation</p>
<table><tr><td>Datum</td><td>Köln, den 28.11.2026</td></tr><tr><td>Betreff</td><td>Betreff: Beschwerde über beschädigtes Produkt</td></tr>
<tr><td>Formell</td><td>Sehr geehrte Damen und Herren, / Sehr geehrter Herr [Name], / Sehr geehrte Frau [Name],</td></tr>
<tr><td>Halbformell</td><td>Liebe Frau [Name], / Lieber Herr [Name], / Liebe Anna,</td></tr></table>
<p class="tip"><b>Exam tip:</b> your own address and the recipient's address are optional. Date, Betreff and Anrede are the essential parts.</p></div>
<div class="card"><h3>2 · Einleitung</h3><p class="en">Introduction: why you write (1–2 sentences)</p>
<ul><li>Beschwerde: ich schreibe Ihnen, weil ich mit … nicht zufrieden bin.</li><li>Anfrage: ich möchte mich über … informieren.</li><li>Kündigung: hiermit möchte ich … kündigen.</li><li>Einladung: ich möchte Sie/dich herzlich zu … einladen.</li><li>Entschuldigung: es tut mir sehr leid, dass …</li></ul>
<p class="ex">Beispiel: Sehr geehrte Damen und Herren, ich schreibe Ihnen, weil ich am 15. Januar ein Produkt bei Ihnen bestellt habe, aber es ist beschädigt angekommen.</p></div>
<div class="card"><h3>3 · Hauptteil</h3><p class="en">Main part: all four content points, 2–3 sentences each, linked logically</p>
<p>Polite requests: <i>Ich möchte Sie bitten, …</i> · <i>Könnten Sie mir bitte mitteilen, …</i></p>
<p class="tip"><b>Tip:</b> number the four points on your paper, write one paragraph per point, tick them off at the end.</p></div>
<div class="card"><h3>4 · Schluss</h3><p class="en">Closing: polite last sentence and sign-off</p>
<ul><li>Ich hoffe auf eine baldige Antwort. <span class="en">I hope for a prompt reply.</span></li><li>Vielen Dank im Voraus für Ihre Hilfe. <span class="en">Thank you in advance.</span></li><li>Ich freue mich auf Ihre Rückmeldung. <span class="en">I look forward to your response.</span></li><li>Für weitere Fragen stehe ich gerne zur Verfügung. <span class="en">I am happy to answer questions.</span></li></ul>
<p><b>Grußformel:</b> formell <i>Mit freundlichen Grüßen</i> · halbformell <i>Viele Grüße / Herzliche Grüße</i> · then your name.</p></div>
</div></section>
<section id="konnektoren"><h2>Konnektoren <small>Connecting words</small></h2>
<div class="grid3">
<div class="card"><h3>Adding</h3><ul><li>außerdem <span class="en">moreover</span></li><li>zusätzlich <span class="en">additionally</span></li><li>darüber hinaus <span class="en">furthermore</span></li></ul></div>
<div class="card"><h3>Contrast</h3><ul><li>jedoch <span class="en">however</span></li><li>leider <span class="en">unfortunately</span></li><li>trotzdem <span class="en">nevertheless</span></li></ul></div>
<div class="card"><h3>Reason</h3><ul><li>deshalb <span class="en">therefore</span></li><li>aus diesem Grund <span class="en">for this reason</span></li><li>deswegen <span class="en">that is why</span></li></ul></div>
<div class="card"><h3>Order</h3><ul><li>zuerst / erstens <span class="en">first</span></li><li>dann <span class="en">then</span></li><li>schließlich <span class="en">finally</span></li></ul></div>
</div><p class="tip"><b>Word order:</b> deshalb, außerdem, trotzdem, leider … take position 1, so the verb comes next: <i>Deshalb mache ich keine Fortschritte.</i> Not: Deshalb ich mache …</p></section>
'''

GRAM = '''
<section id="grammatik"><h2>Grammatik für den Brief <small>Grammar quick reference</small></h2>
<div class="grid">
<div class="card"><h3>Höfliche Bitten mit Modalverben</h3><table>
<tr><td>können</td><td>Könnten Sie mir bitte helfen? <span class="en">Could you please help me?</span></td></tr>
<tr><td>möchten</td><td>Ich möchte mich informieren. <span class="en">I would like to inquire.</span></td></tr>
<tr><td>sollen</td><td>Der Unterricht sollte pünktlich beginnen. <span class="en">Lessons should start on time.</span></td></tr>
<tr><td>müssen</td><td>Ich muss leider absagen. <span class="en">Unfortunately I must cancel.</span></td></tr></table></div>
<div class="card"><h3>Nebensätze: das Verb steht am Ende</h3><table>
<tr><td>weil</td><td>Ich schreibe Ihnen, weil ich mit dem Service nicht zufrieden bin.</td></tr>
<tr><td>dass</td><td>Ich hoffe, dass Sie mir helfen können.</td></tr>
<tr><td>wenn</td><td>Wenn sich nichts ändert, möchte ich kündigen.</td></tr>
<tr><td>ob</td><td>Ich möchte wissen, ob der Kurs noch Plätze hat.</td></tr></table>
<p class="tip">Remember: in a subordinate clause the conjugated verb goes to the END.</p></div>
<div class="card"><h3>Zeit und Grund</h3><table>
<tr><td>am Montag</td><td>on Monday</td></tr><tr><td>um 15 Uhr</td><td>at 3 pm</td></tr><tr><td>im Januar</td><td>in January</td></tr><tr><td>vor zwei Wochen</td><td>two weeks ago</td></tr><tr><td>seit drei Tagen</td><td>for three days (until now)</td></tr>
<tr><td>wegen + Genitiv</td><td>because of (wegen des Problems)</td></tr><tr><td>für + Akkusativ</td><td>for</td></tr><tr><td>zu + Dativ</td><td>to / for</td></tr></table></div>
<div class="card"><h3>Verben mit Präposition</h3><table>
<tr><td>bitten um + Akk.</td><td>Ich bitte Sie um eine schnelle Antwort.</td></tr>
<tr><td>sich beschweren über + Akk.</td><td>Ich möchte mich über den Service beschweren.</td></tr>
<tr><td>sich freuen auf + Akk.</td><td>Ich freue mich auf Ihre Antwort.</td></tr>
<tr><td>sich interessieren für + Akk.</td><td>Ich interessiere mich für den Deutschkurs.</td></tr>
<tr><td>sich bedanken für / bei</td><td>Ich bedanke mich bei dir für deine Hilfe.</td></tr>
<tr><td>sich entschuldigen für</td><td>Ich entschuldige mich für die Verspätung.</td></tr></table></div>
</div></section>
<section id="fehler"><h2>Häufige Fehler <small>Common mistakes</small></h2><div class="grid">
<div class="card"><h3>1 · Not all four points</h3><p class="en">Number the four points on your paper, tick each one off while writing, check at the end.</p></div>
<div class="card"><h3>2 · Mixing du and Sie</h3><p class="en">Decide at the start: formal = Sie + Sehr geehrte…; semi-formal friend = du + Liebe/r…. Do not mix.</p></div>
<div class="card"><h3>3 · Too short</h3><p class="en">Aim for 120–150 words. Two to three sentences per content point, with reasons or examples.</p></div>
<div class="card"><h3>4 · No structure</h3><p class="en">Paragraphs: introduction, main part (1–2 paragraphs), closing. Leave a blank line between them.</p></div>
<div class="card"><h3>5 · No Betreff</h3><p class="en">Always write “Betreff: …” before the salutation in formal letters and emails.</p></div>
<div class="card"><h3>6 · Too complex grammar</h3><p class="en">Simple and correct beats complex and wrong. Use structures you are sure about.</p></div>
<div class="card"><h3>7 · No connectors</h3><p class="en">Use außerdem, deshalb, jedoch, trotzdem to link ideas. This improves your “Kommunikative Gestaltung” score.</p></div>
</div></section>
'''

CSS = '''
:root{--bg:#f4f1ea;--ink:#14262b;--mut:#5b6b70;--card:#fff;--ac:#ffd400;--blue:#1d4f7a;--g:#0b6b4a;--line:#dcd6c6}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 "Segoe UI",system-ui,sans-serif}
header{background:var(--ink);color:#fff;padding:18px 16px 14px}.wrap{max-width:900px;margin:0 auto}
header a{color:#ffd400;text-decoration:none;font-weight:700}h1{margin:.3em 0 .1em;font-size:1.7rem}.sub{margin:0;color:#c9d6d9;font-size:.95rem}
.bar{position:sticky;top:0;z-index:5;background:#fff;border-bottom:1px solid var(--line);padding:8px 12px}.bar .wrap{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.bar a,.bar button{font:700 .85rem inherit;font-family:inherit;color:var(--ink);text-decoration:none;background:#f0ece0;border:1px solid var(--line);border-radius:99px;padding:5px 11px;cursor:pointer}
.bar a:hover,.bar button:hover{background:var(--ac)}.bar .sp{flex:1}
main{max-width:900px;margin:0 auto;padding:6px 14px 90px}section{margin-top:28px}h2{font-size:1.35rem;margin:0 0 10px;border-bottom:3px solid var(--ac);padding-bottom:4px}
h2 small,summary small{font-weight:600;color:var(--mut);font-size:.8rem;margin-left:6px}h3{margin:0 0 4px;font-size:1.02rem}h4{margin:14px 0 6px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px}.card ul{margin:.3em 0;padding-left:1.1em}.card li{margin:.15em 0}
table{border-collapse:collapse;width:100%;font-size:.93rem}td{padding:4px 6px;border-top:1px solid #eee;vertical-align:top}td:first-child{font-weight:700;white-space:nowrap;padding-right:10px}
.tip{background:#fff7cc;border-left:4px solid var(--ac);padding:6px 10px;border-radius:6px;font-size:.92rem;margin:.6em 0 0}.ex{color:var(--blue);font-style:italic;font-size:.93rem}
.en{color:var(--g);font-size:.92rem}body.noen .en{display:none}
details.lt{background:#fff;border:1px solid var(--line);border-radius:12px;margin:8px 0}details.lt>summary{list-style:none;cursor:pointer;padding:12px 14px;display:flex;flex-wrap:wrap;align-items:center;gap:8px}
details.lt>summary::-webkit-details-marker{display:none}details.lt>summary b{font-size:1.1rem}details.lt[open]>summary{border-bottom:1px solid var(--line);background:#faf8f2;border-radius:12px 12px 0 0}
.k{font:800 .68rem system-ui;padding:2px 8px;border-radius:99px;color:#fff}.k.formal{background:var(--blue)}.k.semi{background:#a05a00}
.in{padding:12px 14px}.task{background:#f0ece0;border-radius:10px;padding:8px 12px}.task p{margin:.2em 0}.task ol{margin:.2em 0;padding-left:1.3em}.tl{font-weight:700;font-size:.9rem}
.mail{margin-top:12px;background:#fffef9;border:1px solid var(--line);border-radius:10px;padding:12px 16px}.mail p{margin:.5em 0}.mail .de{font-size:1.05rem}.mail .meta{color:var(--mut);font-size:.92rem}.sal{margin-top:1em}
.wc{color:var(--mut);font-size:.85rem}.tips{background:#fff7cc;border-radius:10px;padding:6px 12px}.tips ul{margin:.3em 0;padding-left:1.1em}
.phg{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:8px}.ph{background:#f0ece0;border-radius:10px;padding:8px 12px}.ph ul{margin:.2em 0;padding-left:1.1em}
@media print{.bar{display:none}details.lt{break-inside:avoid}}
'''

